// Resolve logical image keys (the source file name without extension) to the
// responsive derivatives generated by `npm run images`.
//
// Product photography lives in src/assets/images/Products/1.png … 21.png and is
// exposed as product-1 … product-21 to match the catalogue data. Resolving to
// the generated manifest keeps the multi-megabyte originals out of the bundle.
import { imageManifest } from './generated/imageManifest'

export function resolveImage(name) {
  if (!name) return ''
  // Already a URL or a bundled asset path.
  if (/^(https?:|data:|\/|blob:)/.test(name)) return name
  return imageManifest[name]?.src || name
}

export function imageExists(name) {
  return Boolean(imageManifest[name])
}

export function imageKeys() {
  return Object.keys(imageManifest)
}
